/* eslint-disable */
// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');
import { evolvePath } from "@remotion/paths";

// Preload the primary tech/clean font
const { fontFamily: interFamily } = loadInter();



export type PerformanceCycleProps = Record<string, any>;

const DAYS_DATA = [
  { day: "MON", intensity: 1, label: "Go Hard" },
  { day: "TUE", intensity: 1, label: "Go Hard" },
  { day: "WED", intensity: 0.65, label: "Active Recovery" },
  { day: "THU", intensity: 1, label: "Go Hard" },
  { day: "FRI", intensity: 1, label: "Go Hard" },
  { day: "SAT", intensity: 0.2, label: "Rest" },
  { day: "SUN", intensity: 0.2, label: "Rest" },
];

const GRID_LINES = [
  { label: "PEAK EFFORT", intensity: 1 },
  { label: "RECOVERY", intensity: 0.65 },
  { label: "REST", intensity: 0.2 }
];

const W = 1540;
const H = 600;
const MAX_BAR_H = 400;
const BAR_WIDTH = 90;

const PerformanceCycle: React.FC<PerformanceCycleProps> = ({
  backgroundColor = "#070814",
  transparentBackground = false,
  durationInSeconds = 10,
  peakColor = "#00e5ff",
  recoveryColor = "#9d4edd",
  restColor = "#4a4e69",
  titleText = "Weekly Performance Protocol",
  subtitleText = "2 Days On, 1 Day Off",
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Global layout math
  const points = DAYS_DATA.map((d, i) => {
    const x = (i + 0.5) * (W / DAYS_DATA.length);
    const y = H - d.intensity * MAX_BAR_H;
    return { x, y, ...d };
  });

  // Generate smooth connecting curve
  const PATH_D = points.reduce((acc, curr, i, arr) => {
    if (i === 0) return `M ${curr.x} ${curr.y}`;
    const prev = arr[i - 1];
    const ctrlX = prev.x + (curr.x - prev.x) * 0.5;
    return `${acc} C ${ctrlX} ${prev.y}, ${ctrlX} ${curr.y}, ${curr.x} ${curr.y}`;
  }, "");

  // Timing configurations
  const titleProgress = spring({ frame: frame - 5, fps, config: { damping: 14 } });
  
  const waveStartFrame = 45;
  const waveDuration = 60;
  const pathProgress = interpolate(frame, [waveStartFrame, waveStartFrame + waveDuration], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const evolution = evolvePath(pathProgress, PATH_D);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily, color: "white" }}>
      {/* Background Aesthetics */}
      {!transparentBackground && (
        <>
          <div
            style={{
              position: "absolute",
              inset: 0,
              background: "radial-gradient(circle at center, transparent 20%, rgba(0, 0, 0, 0.85) 120%)",
              pointerEvents: "none",
            }}
          />
          <div
            style={{
              position: "absolute",
              inset: 0,
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              pointerEvents: "none",
            }}
          >
            <div
              style={{
                width: "80%",
                height: "60%",
                backgroundColor: recoveryColor,
                opacity: 0.08,
                filter: "blur(140px)",
                borderRadius: "50%",
              }}
            />
          </div>
        </>
      )}

      {/* Main Layout Container */}
      <div style={{ flex: 1, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", paddingTop: 40 }}>
        
        {/* Title Block */}
        <div
          style={{
            width: W,
            marginBottom: 60,
            opacity: titleProgress,
            transform: `translateY(${(1 - titleProgress) * -20}px)`,
            textAlign: "center",
          }}
        >
          <h1 style={{ fontSize: 56, margin: 0, fontWeight: 800, letterSpacing: "-0.02em" }}>{titleText}</h1>
          <p style={{ color: "rgba(255,255,255,0.6)", fontSize: 26, margin: "16px 0 0 0", fontWeight: 400 }}>{subtitleText}</p>
        </div>

        {/* Graph Area */}
        <div style={{ position: "relative", width: W, height: H }}>
          
          {/* Reference Grid Lines */}
          {GRID_LINES.map((line, i) => {
            const lineY = H - line.intensity * MAX_BAR_H;
            const lineProgress = interpolate(frame, [15 + i * 5, 35 + i * 5], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
            
            return (
              <div
                key={line.label}
                style={{
                  position: "absolute",
                  top: lineY,
                  left: 0,
                  right: 0,
                  height: 1,
                  backgroundColor: "white",
                  opacity: lineProgress * 0.1,
                }}
              >
                <div
                  style={{
                    position: "absolute",
                    left: -140,
                    top: -10,
                    width: 120,
                    textAlign: "right",
                    fontSize: 13,
                    color: "white",
                    opacity: 0.6,
                    fontWeight: 600,
                    letterSpacing: "0.1em",
                  }}
                >
                  {line.label}
                </div>
              </div>
            );
          })}

          {/* Data Bars */}
          {points.map((pt, i) => {
            const color = pt.intensity > 0.8 ? peakColor : pt.intensity > 0.4 ? recoveryColor : restColor;
            const barStartFrame = 20 + i * 4;
            const barProgress = spring({ frame: frame - barStartFrame, fps, config: { damping: 14 } });
            const barH = barProgress * (pt.intensity * MAX_BAR_H);

            return (
              <div
                key={`bar-${i}`}
                style={{
                  position: "absolute",
                  left: pt.x - BAR_WIDTH / 2,
                  bottom: 0,
                  width: BAR_WIDTH,
                  height: Math.max(0, barH),
                  opacity: barProgress,
                }}
              >
                <svg width="100%" height="100%" style={{ overflow: "visible" }}>
                  <defs>
                    <linearGradient id={`bar-grad-${i}`} x1="0" y1="1" x2="0" y2="0">
                      <stop offset="0%" stopColor={color} stopOpacity={0} />
                      <stop offset="100%" stopColor={color} stopOpacity={0.4} />
                    </linearGradient>
                  </defs>
                  <rect width="100%" height="100%" fill={`url(#bar-grad-${i})`} />
                  <line x1="0" y1="0" x2="100%" y2="0" stroke={color} strokeWidth={4} />
                </svg>
              </div>
            );
          })}

          {/* Evolving Wave Line */}
          <svg style={{ position: "absolute", inset: 0, overflow: "visible", pointerEvents: "none" }}>
            <defs>
              <linearGradient id="wave-gradient" x1="0" y1="0" x2={W} y2="0" gradientUnits="userSpaceOnUse">
                {points.map((pt) => {
                  const color = pt.intensity > 0.8 ? peakColor : pt.intensity > 0.4 ? recoveryColor : restColor;
                  return <stop key={`stop-${pt.day}`} offset={`${(pt.x / W) * 100}%`} stopColor={color} />;
                })}
              </linearGradient>
            </defs>
            {/* Outer soft glow path */}
            <path
              d={PATH_D}
              fill="none"
              stroke="url(#wave-gradient)"
              strokeWidth={14}
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeDasharray={evolution.strokeDasharray}
              strokeDashoffset={evolution.strokeDashoffset}
              style={{ filter: "blur(10px)", opacity: 0.6 }}
            />
            {/* Inner crisp path */}
            <path
              d={PATH_D}
              fill="none"
              stroke="url(#wave-gradient)"
              strokeWidth={4}
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeDasharray={evolution.strokeDasharray}
              strokeDashoffset={evolution.strokeDashoffset}
            />
          </svg>

          {/* Interactive Peaks / Dots */}
          {points.map((pt, i) => {
            const color = pt.intensity > 0.8 ? peakColor : pt.intensity > 0.4 ? recoveryColor : restColor;
            // Pop the dot exactly when the drawn wave line hits its horizontal position
            const pointHitFrame = waveStartFrame + (pt.x / W) * waveDuration;
            const dotProgress = spring({ frame: frame - pointHitFrame, fps, config: { damping: 12 } });

            return (
              <div
                key={`dot-${i}`}
                style={{
                  position: "absolute",
                  left: pt.x,
                  top: pt.y,
                  width: 24,
                  height: 24,
                  transform: `translate(-50%, -50%) scale(${Math.max(0, dotProgress)})`,
                  backgroundColor: color,
                  borderRadius: "50%",
                  boxShadow: `0 0 20px ${color}, 0 0 40px ${color}`,
                }}
              >
                <div style={{ position: "absolute", inset: 6, backgroundColor: "white", borderRadius: "50%" }} />
              </div>
            );
          })}

          {/* Bottom Labels */}
          {points.map((pt, i) => {
            const color = pt.intensity > 0.8 ? peakColor : pt.intensity > 0.4 ? recoveryColor : restColor;
            const labelProgress = spring({ frame: frame - (25 + i * 4), fps, config: { damping: 14 } });

            return (
              <div
                key={`label-${i}`}
                style={{
                  position: "absolute",
                  left: pt.x,
                  top: H + 32,
                  transform: `translateX(-50%) translateY(${(1 - labelProgress) * 20}px)`,
                  opacity: labelProgress,
                  display: "flex",
                  flexDirection: "column",
                  alignItems: "center",
                  gap: "8px",
                }}
              >
                <span style={{ color: "white", fontSize: 24, fontWeight: 700, letterSpacing: "0.05em" }}>{pt.day}</span>
                <span style={{ color: color, fontSize: 16, fontWeight: 600, opacity: 0.9, textTransform: "uppercase", whiteSpace: "nowrap" }}>
                  {pt.label}
                </span>
              </div>
            );
          })}

        </div>
      </div>
    </AbsoluteFill>
  );
};

export default PerformanceCycle;